(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18+Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18+Math.sin(x*0.014+t*0.28)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.4)*8+Math.cos((y+w1y)*0.02+t*0.3)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.35)*8+Math.sin((x+w1x)*0.019-t*0.32)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110,80+Math.cos(t*0.35)*60,0.075,2.2,0.9],
    [320+Math.cos(t*0.45)*110,160+Math.sin(t*0.6)*60,0.095,1.8,1.1],
    [240+Math.sin(t*0.28+2)*150,120+Math.cos(t*0.42+1)*100,0.055,2.5,0.7],
    [100+Math.cos(t*0.7+1)*90,190+Math.sin(t*0.55+3)*70,0.11,1.6,1.2],
    [380+Math.sin(t*0.38+4)*100,55+Math.cos(t*0.8+2)*80,0.065,2.8,0.6],
    [240+Math.cos(t*0.32+5)*130,210+Math.sin(t*0.48)*90,0.085,2.0,1.0],
    [60+Math.sin(t*0.6+3)*70,50+Math.cos(t*0.5+4)*50,0.1,1.4,1.3],
    [420+Math.cos(t*0.42+2)*80,200+Math.sin(t*0.65+1)*60,0.07,2.4,0.8]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp),b=Math.sin(d*f*0.7+t*sp*0.6+1.5),m=Math.sin(d*f*1.3-t*sp*0.8+3.0);
    aS+=a*w;iS+=b*w;mS+=m*w;
  }
  const tw=src.reduce((a,s)=>a+s[4],0);
  aS/=tw;iS/=tw;mS/=tw;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.035+t*1.0)+Math.sin(sx*0.015+sy*0.04-t*0.5))/3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*5-t*1.0)+Math.sin(dist*0.06-ang*2-t*1.8))*0.3;
  const modulator=Math.sin(mS*Math.PI*0.5)*0.4;
  const rd1=Math.tanh((aS-iS*0.65+bg*0.25+spiral+modulator)*2.0);
  const rd2=Math.tanh((iS*0.8-aS*0.4+bg*0.4-spiral*0.5)*1.8);
  const coupled=Math.tanh((rd1*0.7+rd2*0.3+Math.sin((sx-sy)*0.08+t*1.5)*0.2)*1.6);
  const cell=Math.tanh((Math.sin(sx*0.12)*Math.sin(sy*0.12)+Math.sin((sx+sy)*0.08+t)*0.4+Math.sin(sx*0.06-t*0.3)*Math.cos(sy*0.09+t*0.2))*1.3)*0.2;
  const grain=Math.sin(sx*1.7+t*3)*Math.sin(sy*2.3-t*2.5)*0.04;
  const blend=coupled*0.7+cell*0.25+grain;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,95],[18,90,120],[28,140,135],[60,170,130],
    [180,190,80],[220,170,65],[230,130,70],[210,85,75],[160,50,70],
    [90,25,65],[40,15,55],[6,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const edge=Math.abs(coupled)>0.65?1.2:1.0;
  const glow=Math.max(0,coupled-0.3)*0.3;
  const pulse=0.92+Math.sin(t*0.8)*0.08;
  const lum=(0.85+Math.sin(coupled*Math.PI)*0.15)*edge*pulse;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  return[
    Math.min(255,((r0+glow*60)*lum)|0),
    Math.min(255,((g0+glow*40)*lum)|0),
    Math.min(255,((b0+glow*30)*lum)|0)
  ];
}
